1	import java.util.*;
2	import java.util.function.BiFunction;
3	
4	/**
5	 * A simple predator-prey simulator, based on a rectangular field
6	 * containing different organisms.
7	 *
8	 * @version 2022.03.02
9	 */
10	public class Simulator implements SimulationControls
11	{
12	    private boolean playingSimulation = false;
13	    private int remainingSteps;
14	
15	    private static final Random rand = Randomizer.getRandom();
16	
17	    // The default width for the grid.
18	    private static final int DEFAULT_WIDTH = 240;
19	    // The default depth of the grid.
20	    private static final int DEFAULT_DEPTH = 160;
21	
22	    // Maximum number of hunters allowed in the simulation
23	    private static final int HUNTER_LIMIT = 5;
24	    private int hunterCount = 0;
25	
26	    // Creation probability for each actor class (instance field — not shared across instances)
27	    private Map<Class<?>, Double> CREATION_PROBABILITIES = Map.ofEntries(
28	            Map.entry(Coyote.class, 0.010),
29	            Map.entry(Deer.class,   0.080),
30	            Map.entry(Wolf.class,   0.010),
31	            Map.entry(Eagle.class,  0.010),
32	            Map.entry(Mouse.class,  0.080),
33	            Map.entry(Grass.class,  0.030),
34	            Map.entry(Hunter.class, 0.030)
35	    );
36	
37	    // List of actors in the field.
38	    private List<Actor> actors;
39	    // The current state of the field.
40	    private Field field;
41	    // The current step of the simulation.
42	    private int step;
43	    // A graphical view of the simulation.
44	    private SimulatorView view;
45	    // Environment in the simulation.
46	    private Environment environment;
47	
48	
49	    /**
50	     * A simulator constructor that sets a custom creation probability for each actor class.
51	     * Useful for testing different probability combinations to find an optimal configuration.
52	     */
53	    public Simulator(double GrassProbability, double DeerProbability, double CoyoteProbability,
54	                     double WolfProbability, double EagleProbability, double HunterProbability,
55	                     double MouseProbability)
56	    {
57	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
58	        CREATION_PROBABILITIES = Map.ofEntries(
59	                Map.entry(Coyote.class, CoyoteProbability),
60	                Map.entry(Deer.class,   DeerProbability),
61	                Map.entry(Wolf.class,   WolfProbability),
62	                Map.entry(Eagle.class,  EagleProbability),
63	                Map.entry(Mouse.class,  MouseProbability),
64	                Map.entry(Grass.class,  GrassProbability),
65	                Map.entry(Hunter.class, HunterProbability)
66	        );
67	        reset();
68	    }
69	
70	    /** Construct a simulation field with default size. */
71	    public Simulator()
72	    {
73	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
74	    }
75	
76	    /**
77	     * Create a simulation field with the given size.
78	     * @param depth Depth of the field. Must be greater than zero.
79	     * @param width Width of the field. Must be greater than zero.
80	     */
81	    public Simulator(int depth, int width)
82	    {
83	        if (width <= 0 || depth <= 0) {
84	            System.out.println("The dimensions must be greater than zero.");
85	            System.out.println("Using default values.");
86	            depth = DEFAULT_DEPTH;
87	            width = DEFAULT_WIDTH;
88	        }
89	
90	        actors = new ArrayList<>();
91	        field = new Field(depth, width);
92	        environment = new Environment(new Time(), new Weather());
93	
94	        view = new SimulatorView(depth, width);
95	        for (Class cls : SimulationInfo.DEFAULT_COLOR_MAP.keySet()) {
96	            view.setColor(cls, SimulationInfo.DEFAULT_COLOR_MAP.get(cls));
97	        }
98	        view.wireButtons(this);
99	
100	        reset();
101	    }
102	
103	    // --- SimulationControls implementation ---
104	
105	    @Override
106	    public void stepOnce()
107	    {
108	        if (!playingSimulation) {
109	            playingSimulation = true;
110	            simulateOneStep();
111	            playingSimulation = false;
112	        }
113	    }
114	
115	    @Override
116	    public void runLongSimulation()
117	    {
118	        remainingSteps += 4000;
119	        simulate(remainingSteps);
120	    }
121	
122	    @Override
123	    public void stop()
124	    {
125	        playingSimulation = false;
126	    }
127	
128	    @Override
129	    public void reset()
130	    {
131	        step = 0;
132	        hunterCount = 0;
133	        actors.clear();
134	        populate();
135	        environment.getTime().reset();
136	        view.showStatus(step, environment, field);
137	    }
138	
139	    @Override
140	    public boolean isPlaying()
141	    {
142	        return playingSimulation;
143	    }
144	
145	    // --- Simulation engine ---
146	
147	    /**
148	     * Run the simulation from its current state for the given number of steps.
149	     * Stops early if the population ceases to be viable.
150	     */
151	    public void simulate(int numSteps)
152	    {
153	        playingSimulation = true;
154	        remainingSteps = numSteps;
155	
156	        int stepsDone = 1;
157	        while (playingSimulation) {
158	            for (int s = 1; s <= numSteps && view.isViable(field); s++) {
159	                simulateOneStep();
160	                stepsDone++;
161	            }
162	            if (!view.isViable(field)) {
163	                if (stepsDone > SimulationInfo.HIGHEST_STEPS) {
164	                    SimulationInfo.HIGHEST_STEPS = stepsDone;
165	                    SimulationInfo.HIGHEST_STEP_PROBS = this.CREATION_PROBABILITIES;
166	                }
167	                playingSimulation = false;
168	                break;
169	            }
170	        }
171	        remainingSteps = numSteps - stepsDone;
172	    }
173	
174	    /**
175	     * Run the simulation from its current state for a single step.
176	     * Iterates over the whole field, letting each actor act.
177	     */
178	    public void simulateOneStep()
179	    {
180	        if (!playingSimulation) { return; }
181	        step++;
182	        environment.getTime().incrementTime();
183	        environment.getWeather().checkWeatherChange(step);
184	
185	        List<Actor> newActors = new ArrayList<>();
186	        for (Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
187	            Actor actor = it.next();
188	            actor.act(newActors, environment);
189	            if (!actor.isAlive()) {
190	                it.remove();
191	            }
192	        }
193	        actors.addAll(newActors);
194	        plantGrassInPatches();
195	
196	        view.showStatus(step, environment, field);
197	    }
198	
199	    /**
200	     * Randomly generate grass in free patches on the field, only if it is raining.
201	     */
202	    private void plantGrassInPatches()
203	    {
204	        for (Location location : field.getRandomFreePatches(CREATION_PROBABILITIES.get(Grass.class))) {
205	            if (rand.nextDouble() <= CREATION_PROBABILITIES.get(Grass.class)
206	                    && environment.getWeather().getCurrentWeather() == WeatherType.RAINING) {
207	                actors.add(new Grass(field, location));
208	            }
209	        }
210	    }
211	
212	    /**
213	     * Randomly populate the field with organisms.
214	     * The factory map determines which actor is spawned at each cell; entries
215	     * are tried in insertion order and only the first match is placed per cell.
216	     */
217	    private void populate()
218	    {
219	        LinkedHashMap<Class<?>, BiFunction<Location, Animal.Gender, Actor>> factories = new LinkedHashMap<>();
